// ---------------- BRUTE ----------------
ll solve_brute(int n,int m,int t, vector<array<int,3>>& E){
    if(n==1) return t;
    vector<vector<pair<int,int>>> adj(n+1);
    for(auto&e:E){int u=e[0],v=e[1],w=e[2];adj[u].push_back({v,w});adj[v].push_back({u,w});}
    // exact min path sum D via Dijkstra on states (prev,cur)
    int NN=(n+1)*(n+1);
    vector<ll> d(NN,INF);
    priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>> pq;
    for(auto&e:adj[n]){int x=e.first,w=e.second;int st=n*(n+1)+x;if(d[st]>w){d[st]=w;pq.push({w,st});}}
    ll D=INF;
    while(!pq.empty()){auto pr=pq.top();pq.pop();ll dd=pr.first;int st=pr.second;if(dd!=d[st])continue;int prev=st/(n+1),cur=st%(n+1);if(cur==1){D=dd;break;}for(auto&e:adj[cur]){int y=e.first,w=e.second;if(y==prev)continue;int ns=cur*(n+1)+y;if(d[ns]>dd+w){d[ns]=dd+w;pq.push({d[ns],ns});}}}
    // BFS over (prev,cur,sum) up to CAP
    int64_t CAP=(int64_t)t+3000;
    // visited dimensions: (n+1)*(n+1)*(CAP+1)
    int P=n+1;
    vector<char> vis((size_t)P*P*(CAP+1),0);
    auto vidx=[&](int prev,int cur,int s)->size_t{return ((size_t)prev*P+cur)*(CAP+1)+s;};
    struct Node{int prev,cur,s;};
    vector<Node> q; q.reserve(1000000);
    q.push_back({0,n,0}); vis[vidx(0,n,0)]=1;
    int bestBelow=-1; ll bestAbove=INF;
    size_t head=0;
    while(head<q.size()){
        Node nd=q[head++];
        if(nd.cur==1){ if(nd.s<=t){if(nd.s>bestBelow)bestBelow=nd.s;} else {if((ll)nd.s<bestAbove)bestAbove=nd.s;} continue; }
        for(auto&e:adj[nd.cur]){int y=e.first,w=e.second;if(y==nd.prev)continue;int ns2=nd.s+w;if(ns2>CAP)continue;size_t ii=vidx(nd.cur,y,ns2);if(vis[ii])continue;vis[ii]=1;q.push_back({nd.cur,y,ns2});}
    }
    ll ans=INF;
    if(D>t){ ans=D-t; }
    else {
        if(bestBelow>=0) ans=min(ans,(ll)t-bestBelow);
        if(bestAbove<INF) ans=min(ans,bestAbove-(ll)t);
    }
    return ans;
}

